    16	module cva6_fifo_v3 #(
    17	    parameter bit FALL_THROUGH = 1'b0,  // fifo is in fall-through mode
    18	    parameter bit FPGA_ALTERA = 1'b0,  // FPGA Altera optimizations enabled
    19	    parameter int unsigned DATA_WIDTH = 32,  // default data width if the fifo is of type logic
    20	    parameter int unsigned DEPTH = 8,  // depth can be arbitrary from 0 to 2**32
    21	    parameter type dtype = logic [DATA_WIDTH-1:0],
    22	    parameter bit FPGA_EN = 1'b0,
    23	    // DO NOT OVERWRITE THIS PARAMETER
    24	    parameter int unsigned ADDR_DEPTH = (DEPTH > 1) ? $clog2(DEPTH) : 1
    25	) (
    26	    input  logic                  clk_i,       // Clock
    27	    input  logic                  rst_ni,      // Asynchronous reset active low
    28	    input  logic                  flush_i,     // flush the queue
    29	    input  logic                  testmode_i,  // test_mode to bypass clock gating
    30	    // status flags
    31	    output logic                  full_o,      // queue is full
    32	    output logic                  empty_o,     // queue is empty
    33	    output logic [ADDR_DEPTH-1:0] usage_o,     // fill pointer
    34	    // as long as the queue is not full we can push new data
    35	    input  dtype                  data_i,      // data to push into the queue
    36	    input  logic                  push_i,      // data is valid and can be pushed to the queue
    37	    // as long as the queue is not empty we can pop new elements
    38	    output dtype                  data_o,      // output data
    39	    input  logic                  pop_i        // pop head from queue
    40	);
    41	  // local parameter
    42	  // FIFO depth - handle the case of pass-through, synthesizer will do constant propagation
    43	  localparam int unsigned FifoDepth = (DEPTH > 0) ? DEPTH : 1;
    44	  // clock gating control
    45	  logic gate_clock;
    46	  // pointer to the read and write section of the queue
    47	  logic [ADDR_DEPTH - 1:0] read_pointer_n, read_pointer_q, write_pointer_n, write_pointer_q;
    48	  // keep a counter to keep track of the current queue status
    49	  // this integer will be truncated by the synthesis tool
    50	  logic [ADDR_DEPTH:0] status_cnt_n, status_cnt_q;
    51	  // actual memory
    52	  dtype [FifoDepth - 1:0] mem_n, mem_q;
    53	  dtype data_ft_n, data_ft_q;
    54	  logic first_word_n, first_word_q;
    55	
    56	  // fifo ram signals for fpga target
    57	  logic fifo_ram_we;
    58	  logic [ADDR_DEPTH-1:0] fifo_ram_read_address;
    59	  logic [ADDR_DEPTH-1:0] fifo_ram_write_address;
    60	  logic [$bits(dtype)-1:0] fifo_ram_wdata;
    61	  logic [$bits(dtype)-1:0] fifo_ram_rdata;
    62	
    63	  assign usage_o = status_cnt_q[ADDR_DEPTH-1:0];
    64	
    65	  if (DEPTH == 0) begin : gen_pass_through
    66	    assign empty_o = ~push_i;
    67	    assign full_o  = ~pop_i;
    68	  end else begin : gen_fifo
    69	    assign full_o  = (status_cnt_q == FifoDepth[ADDR_DEPTH:0]);
    70	    assign empty_o = (status_cnt_q == 0) & ~(FALL_THROUGH & push_i);
    71	  end
    72	  // status flags
    73	
    74	  // read and write queue logic
    75	  always_comb begin : read_write_comb
    76	    // default assignment
    77	    read_pointer_n  = read_pointer_q;
    78	    write_pointer_n = write_pointer_q;
    79	    status_cnt_n    = status_cnt_q;
    80	    if (FPGA_EN && FPGA_ALTERA) data_ft_n = data_ft_q;
    81	    if (FPGA_EN && FPGA_ALTERA) first_word_n = first_word_q;
    82	    if (FPGA_EN) begin
    83	      fifo_ram_we            = '0;
    84	      fifo_ram_write_address = '0;
    85	      fifo_ram_wdata         = '0;
    86	      if (DEPTH == 0) begin
    87	        data_o = data_i;
    88	      end else begin
    89	        if (FPGA_ALTERA) data_o = first_word_q ? data_ft_q : fifo_ram_rdata;
    90	        else data_o = fifo_ram_rdata;
    91	      end
    92	    end else begin
    93	      data_o     = (DEPTH == 0) ? data_i : mem_q[read_pointer_q];
    94	      mem_n      = mem_q;
    95	      gate_clock = 1'b1;
    96	    end
    97	
    98	    // push a new element to the queue
    99	    if (push_i && ~full_o) begin
   100	      if (FPGA_EN) begin
   101	        fifo_ram_we = 1'b1;
   102	        fifo_ram_write_address = write_pointer_q;
   103	        fifo_ram_wdata = data_i;
   104	        if (FPGA_ALTERA) first_word_n = first_word_q && pop_i;
   105	      end else begin
   106	        // push the data onto the queue
   107	        mem_n[write_pointer_q] = data_i;
   108	        // un-gate the clock, we want to write something
   109	        gate_clock = 1'b0;
   110	      end
   111	
   112	      // increment the write counter
   113	      if (write_pointer_q == FifoDepth[ADDR_DEPTH-1:0] - 1) write_pointer_n = '0;
   114	      else write_pointer_n = write_pointer_q + 1;
   115	      // increment the overall counter
   116	      status_cnt_n = status_cnt_q + 1;
   117	    end
   118	
   119	    if (pop_i && ~empty_o) begin
   120	      data_ft_n = data_i;
   121	      if (FPGA_EN && FPGA_ALTERA) first_word_n = first_word_q && push_i;
   122	      // read from the queue is a default assignment
   123	      // but increment the read pointer...
   124	      if (read_pointer_n == FifoDepth[ADDR_DEPTH-1:0] - 1) read_pointer_n = '0;
   125	      else read_pointer_n = read_pointer_q + 1;
   126	      // ... and decrement the overall count
   127	      status_cnt_n = status_cnt_q - 1;
   128	    end
   129	
   130	    // keep the count pointer stable if we push and pop at the same time
   131	    if (push_i && pop_i && ~full_o && ~empty_o) status_cnt_n = status_cnt_q;
   132	
   133	    // FIFO is in pass through mode -> do not change the pointers
   134	    if ((FALL_THROUGH || (FPGA_EN && FPGA_ALTERA)) && (status_cnt_q == 0) && push_i) begin
   135	      if (FALL_THROUGH) data_o = data_i;
   136	      if (FPGA_EN && FPGA_ALTERA) begin
   137	        data_ft_n = data_i;
   138	        first_word_n = '1;
   139	      end
   140	      if (pop_i) begin
   141	        first_word_n = '0;
   142	        status_cnt_n = status_cnt_q;
   143	        read_pointer_n = read_pointer_q;
   144	        write_pointer_n = write_pointer_q;
   145	      end
   146	    end
   147	
   148	    if (FPGA_EN) fifo_ram_read_address = (FPGA_ALTERA == 1) ? read_pointer_n : read_pointer_q;
   149	    else fifo_ram_read_address = '0;
   150	
   151	  end
   152	
   153	  // sequential process
   154	  always_ff @(posedge clk_i or negedge rst_ni) begin
   155	    if (~rst_ni) begin
   156	      read_pointer_q  <= '0;
   157	      write_pointer_q <= '0;
   158	      status_cnt_q    <= '0;
   159	      if (FPGA_ALTERA) first_word_q <= '0;
   160	      if (FPGA_ALTERA) data_ft_q <= '0;
   161	    end else begin
   162	      if (flush_i) begin
   163	        read_pointer_q  <= '0;
   164	        write_pointer_q <= '0;
   165	        status_cnt_q    <= '0;
   166	        if (FPGA_ALTERA) first_word_q <= '0;
   167	        if (FPGA_ALTERA) data_ft_q <= '0;
   168	      end else begin
   169	        read_pointer_q  <= read_pointer_n;
   170	        write_pointer_q <= write_pointer_n;
   171	        status_cnt_q    <= status_cnt_n;
   172	        if (FPGA_ALTERA) data_ft_q <= data_ft_n;
   173	        if (FPGA_ALTERA) first_word_q <= first_word_n;
   174	      end
   175	    end
   176	  end
   177	
   178	  if (FPGA_EN) begin : gen_fpga_queue
   179	    if (FPGA_ALTERA) begin
   180	      SyncDpRam_ind_r_w #(
   181	          .ADDR_WIDTH(ADDR_DEPTH),
   182	          .DATA_DEPTH(DEPTH),
   183	          .DATA_WIDTH($bits(dtype))
   184	      ) fifo_ram (
   185	          .Clk_CI   (clk_i),
   186	          .WrEn_SI  (fifo_ram_we),
   187	          .RdAddr_DI(fifo_ram_read_address),
   188	          .WrAddr_DI(fifo_ram_write_address),
   189	          .WrData_DI(fifo_ram_wdata),
   190	          .RdData_DO(fifo_ram_rdata)
   191	      );
   192	    end else begin
   193	      AsyncDpRam #(
   194	          .ADDR_WIDTH(ADDR_DEPTH),
   195	          .DATA_DEPTH(DEPTH),
   196	          .DATA_WIDTH($bits(dtype))
   197	      ) fifo_ram (
   198	          .Clk_CI   (clk_i),
   199	          .WrEn_SI  (fifo_ram_we),
   200	          .RdAddr_DI(fifo_ram_read_address),
   201	          .WrAddr_DI(fifo_ram_write_address),
   202	          .WrData_DI(fifo_ram_wdata),
   203	          .RdData_DO(fifo_ram_rdata)
   204	      );
   205	    end
   206	  end else begin : gen_asic_queue
   207	    always_ff @(posedge clk_i or negedge rst_ni) begin
   208	      if (~rst_ni) begin
   209	        mem_q <= '0;
   210	      end else if (!gate_clock) begin
   211	        mem_q <= mem_n;
   212	      end
   213	    end
   214	  end
   215	
   216	  // pragma translate_off
   217	  initial begin
   218	    assert (DEPTH > 0)
   219	    else $error("DEPTH must be greater than 0.");
   220	  end
   221	
   222	  full_write :
   223	  assert property (@(posedge clk_i) disable iff (~rst_ni) (full_o |-> ~push_i))
   224	  else $fatal(1, "Trying to push new data although the FIFO is full.");
   225	
   226	  empty_read :
   227	  assert property (@(posedge clk_i) disable iff (~rst_ni) (empty_o |-> ~pop_i))
   228	  else $fatal(1, "Trying to pop data although the FIFO is empty.");
   229	  // pragma translate_on
   230	
   231	endmodule  // fifo_v3

